//! Emit per-byte boundary priors for a corpus, using the *shipping* implementation.
//!
//! Training priors and inference priors have to come from the same code, or the model
//! learns against a proposal distribution it never sees again. So training data is
//! generated by this binary rather than by the Python port:
//!
//!     emit-priors --unidic data/priors/jpn-unidic.bin --wordbank-dir data/wordbanks \
//!         --out data/processed/train.priors < data/processed/train.jsonl
//!
//! Input is one JSON object per line with `text` and `lang`. Without `--out` it writes one
//! JSON object per line with `prior` (used by the parity test against `tagger/prior.py`);
//! with `--out` it writes the packed sidecar the dataloader indexes by record number, which
//! also takes the Viterbi off the training hot path entirely.
use std::collections::HashMap;
use std::fs::File;
use std::io::{self, BufRead, BufWriter, Write};
use std::path::{Path, PathBuf};

use anyhow::Result;
use lexide::segment::prior::{prior_ids, proposal_spans, Proposer, Wordbank};
use lexide::segment::unidic::UniDic;

/// `LXPRIOR\x01`, then u64 count, u64 offsets[count+1], then the concatenated id bytes.
const SIDECAR_MAGIC: &[u8; 8] = b"LXPRIOR\x01";

fn main() -> Result<()> {
    let mut wordbank_dir = PathBuf::from("data/wordbanks");
    let mut unidic_path: Option<PathBuf> = None;
    let mut out_path: Option<PathBuf> = None;
    let mut max_bytes = 512usize;
    let mut group_unknown = true;
    let mut spans_mode = false;
    let mut args = std::env::args().skip(1);
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--wordbank-dir" => wordbank_dir = PathBuf::from(args.next().unwrap_or_default()),
            "--unidic" => unidic_path = Some(PathBuf::from(args.next().unwrap_or_default())),
            "--out" => out_path = Some(PathBuf::from(args.next().unwrap_or_default())),
            "--max-bytes" => max_bytes = args.next().unwrap_or_default().parse()?,
            "--no-group-unknown" => group_unknown = false,
            "--spans" => spans_mode = true,
            other => anyhow::bail!("unknown argument {other}"),
        }
    }

    let unidic = match &unidic_path {
        Some(p) => {
            eprintln!("loading unidic artifact {}", p.display());
            Some(UniDic::load(p)?)
        }
        None => None,
    };

    // A language's proposer, resolved once: the bundled dictionary for Japanese, a corpus
    // wordbank where we have one, whitespace otherwise.
    let mut proposers: HashMap<String, Option<Box<dyn Proposer>>> = HashMap::new();
    let resolve = |lang: &str, dir: &Path| -> Option<Box<dyn Proposer>> {
        let path = dir.join(format!("{lang}.tsv"));
        if path.exists() {
            if let Ok(wb) = Wordbank::load(&path, group_unknown) {
                return Some(Box::new(wb));
            }
        }
        None
    };

    let stdin = io::stdin();
    let mut jsonl = BufWriter::new(io::stdout().lock());
    let mut blob: Vec<u8> = Vec::new();
    let mut offsets: Vec<u64> = vec![0];

    for line in stdin.lock().lines() {
        let line = line?;
        if line.trim().is_empty() {
            continue;
        }
        let v: serde_json::Value = serde_json::from_str(&line)?;
        let text = v.get("text").and_then(|t| t.as_str()).unwrap_or_default();
        let lang = v.get("lang").and_then(|l| l.as_str()).unwrap_or_default();

        let chosen: Option<&dyn Proposer> = if lang == "jpn" && unidic.is_some() {
            unidic.as_ref().map(|d| d as &dyn Proposer)
        } else {
            proposers
                .entry(lang.to_string())
                .or_insert_with(|| resolve(lang, &wordbank_dir))
                .as_deref()
        };
        if spans_mode {
            writeln!(jsonl, "{}", serde_json::json!({ "spans": proposal_spans(text, chosen) }))?;
            continue;
        }
        let ids = prior_ids(text, chosen, max_bytes);

        if out_path.is_some() {
            blob.extend_from_slice(&ids);
            offsets.push(blob.len() as u64);
        } else {
            writeln!(jsonl, "{}", serde_json::json!({ "prior": ids }))?;
        }
    }

    if let Some(path) = out_path {
        let n = offsets.len() as u64 - 1;
        let mut f = BufWriter::new(File::create(&path)?);
        f.write_all(SIDECAR_MAGIC)?;
        f.write_all(&n.to_le_bytes())?;
        for off in &offsets {
            f.write_all(&off.to_le_bytes())?;
        }
        f.write_all(&blob)?;
        f.flush()?;
        eprintln!(
            "wrote {} ({n} records, {:.1} MB)",
            path.display(),
            blob.len() as f64 / 1048576.0
        );
    } else {
        jsonl.flush()?;
    }
    Ok(())
}
